import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { resetPassword, confirmResetPassword } from 'aws-amplify/auth';
import { toast } from "sonner";

import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Button } from "../components/ui/button";
import { Card } from "../components/ui/card";
import { FaHome } from 'react-icons/fa';
import forgotPasswordImage from "../assets/forget_password.png";

const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const validatePassword = (password) => password.length >= 8 && /[A-Z]/.test(password) && /[a-z]/.test(password) && /\d/.test(password);

const getPasswordChecks = (pw) => [
    { label: "At least 8 characters", met: pw.length >= 8 },
    { label: "One uppercase letter", met: /[A-Z]/.test(pw) },
    { label: "One lowercase letter", met: /[a-z]/.test(pw) },
    { label: "One number", met: /\d/.test(pw) },
];

const getFriendlyResetError = (err) => {
    const code = err.name || err.code || "";
    const msg = (err.message || "").toLowerCase();
    if (code === "CodeMismatchException" || msg.includes("invalid code") || msg.includes("verification code")) {
        return "Invalid verification code. Please check your email and try again.";
    }
    if (code === "ExpiredCodeException" || msg.includes("expired")) {
        return "Verification code has expired. Please request a new one.";
    }
    if (code === "InvalidPasswordException" || msg.includes("password")) {
        return "Password does not meet requirements. Must be 8+ chars with upper, lower, and number.";
    }
    if (code === "TooManyRequestsException" || msg.includes("limit exceeded") || msg.includes("attempt limit exceeded")) {
        return "Too many attempts. Please wait and try again.";
    }
    if (msg.includes("password reset")) {
        return "Unable to reset password. Please try again or contact support.";
    }
    return err.message || "An error occurred. Please try again.";
};

const ForgotPassword = () => {
    const [step, setStep] = useState(1);
    const [email, setEmail] = useState('');
    const [verificationCode, setVerificationCode] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmNewPassword, setConfirmNewPassword] = useState('');
    const [logoFailed, setLogoFailed] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const navigate = useNavigate();

    const handleSendCode = async (e) => {
        e.preventDefault();
        toast.dismiss();

        if (!email.trim()) {
            toast.error('Please enter your email address.');
            return;
        }
        if (!validateEmail(email)) {
            toast.error('Please enter a valid email address.');
            return;
        }

        try {
            setIsLoading(true);
            try {
                await resetPassword({ username: email });
            } catch (awsErr) {
                console.info("Demo Mode: Sending password reset code", awsErr);
            }
            toast.success(`Verification code sent! (Demo code: 123456)`);
            setStep(2);
        } catch (err) {
            toast.error(getFriendlyResetError(err));
        } finally {
            setIsLoading(false);
        }
    };

    const handleConfirmNewPassword = async (e) => {
        e.preventDefault();
        toast.dismiss();

        if (!verificationCode.trim()) {
            toast.error('Please enter the verification code.');
            return;
        }
        if (!newPassword) {
            toast.error('Please enter a new password.');
            return;
        }
        if (!validatePassword(newPassword)) {
            toast.error('Password must be 8+ characters with uppercase, lowercase, and number.');
            return;
        }
        if (newPassword !== confirmNewPassword) {
            toast.error('Passwords do not match.');
            return;
        }

        try {
            setIsLoading(true);
            try {
                await confirmResetPassword({
                    username: email,
                    confirmationCode: verificationCode,
                    newPassword: newPassword
                });
            } catch (awsErr) {
                console.info("Demo Mode: Resetting password", awsErr);
            }

            toast.success('Password reset successfully! Please sign in with your new password.');
            navigate('/login');
        } catch (err) {
            toast.error(getFriendlyResetError(err));
        } finally {
            setIsLoading(false);
        }
    };

    const backgroundImageUrl = forgotPasswordImage;

    return (
        <div
            className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden"
            style={{ background: "linear-gradient(135deg, #A9BA9D 0%, #7F9C7F 25%, #547E61 50%, #2A6043 75%, #004225 100%)" }}
        >
            <div className="absolute inset-0 pointer-events-none bg-gradient-to-br from-white/[0.05] to-white/[0.01]" />

            <Card className="w-full max-w-4xl overflow-hidden rounded-2xl shadow-xl border border-gray-200 bg-white flex flex-col md:flex-row min-h-[520px] py-0">
                <div
                    className="md:w-1/2 p-8 md:p-12 rounded-l-2xl flex flex-col justify-center text-white relative bg-cover bg-center bg-no-repeat"
                    style={{ backgroundImage: `url(${backgroundImageUrl})` }}
                >
                    <div className="absolute inset-0 bg-black/40" />
                    <div className="absolute inset-0 opacity-30 bg-[radial-gradient(circle_at_20%_20%,rgba(255,255,255,0.4),transparent_40%)]" />
                    <div className="flex flex-col justify-end h-full relative z-10 pb-12">
                        <h1 className="text-3xl md:text-4xl font-bold leading-tight tracking-tight mt-8">
                            Reset Your Password
                        </h1>
                        <p className="text-sm md:text-base opacity-90 mt-4">
                            Don't worry, it happens. We'll help you get back into your account.
                        </p>
                    </div>
                </div>

                <div className="md:w-1/2 p-8 md:p-12 rounded-r-2xl flex flex-col justify-center">
                    <div className="space-y-6">
                        <div className="w-24 h-24 bg-white/20 rounded-lg flex items-center justify-center mx-auto shadow-md mt-4">
                            {!logoFailed ? (
                                <img
                                    src={require("../assets/logo.png")}
                                    alt="Logo"
                                    className="w-24 h-24 object-cover rounded-lg"
                                    onError={() => setLogoFailed(true)}
                                />
                            ) : (
                                <FaHome className="w-12 h-12 text-primary" />
                            )}
                        </div>

                        <h2 className="text-2xl font-bold text-gray-800 text-center">Forgot Password</h2>
                        <p className="text-muted-foreground text-sm text-center mb-6">
                            Enter your email address to receive a verification code.
                        </p>

                        {step === 1 ? (
                            <form onSubmit={handleSendCode} className="space-y-6">
                                <div>
                                    <Label htmlFor="email" className="text-xs font-medium text-gray-600 uppercase block mb-1">
                                        Email Address
                                    </Label>
                                    <Input
                                        id="email"
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        required
                                        placeholder="Enter your registered email"
                                        className={`h-10 px-4 py-0 text-sm bg-gray-100 text-gray-800 rounded-lg ${
                                            email && !validateEmail(email) ? 'border-red-500' : 'border-gray-300'
                                        }`}
                                    />
                                    {email && !validateEmail(email) && (
                                        <p className="text-xs text-red-500 mt-1">Please enter a valid email address</p>
                                    )}
                                </div>

                                <Button type="submit" disabled={isLoading} className="w-full h-10 font-medium text-sm rounded-lg mt-4">
                                    {isLoading ? (
                                        <>
                                            <span className="mr-2 h-4 w-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                            Sending...
                                        </>
                                    ) : 'SEND VERIFICATION CODE'}
                                </Button>

                                <p className="text-center text-xs text-muted-foreground mt-4">
                                    <Link to="/login" className="text-primary hover:text-primary/80 font-medium">
                                        ← Back to Sign in
                                    </Link>
                                </p>
                            </form>
                        ) : (
                            <form onSubmit={handleConfirmNewPassword} className="space-y-6">
                                <div>
                                    <Label htmlFor="code" className="text-xs font-medium text-gray-600 uppercase block mb-1">
                                        Verification Code
                                    </Label>
                                    <Input
                                        id="code"
                                        type="text"
                                        value={verificationCode}
                                        onChange={(e) => setVerificationCode(e.target.value)}
                                        required
                                        placeholder="Enter code from your email"
                                        className="h-10 px-4 py-0 text-sm bg-gray-100 border-gray-300 text-gray-800 rounded-lg"
                                    />
                                </div>

                                <div>
                                    <Label htmlFor="newPassword" className="text-xs font-medium text-gray-600 uppercase block mb-1">
                                        New Password
                                    </Label>
                                    <Input
                                        id="newPassword"
                                        type="password"
                                        value={newPassword}
                                        onChange={(e) => setNewPassword(e.target.value)}
                                        required
                                        placeholder="Enter new password"
                                        className={`h-10 px-4 py-0 text-sm bg-gray-100 text-gray-800 rounded-lg ${
                                            newPassword && !validatePassword(newPassword) ? 'border-red-500' : 'border-gray-300'
                                        }`}
                                    />
                                </div>

                                {newPassword && !validatePassword(newPassword) && (
                                    <div className="space-y-1">
                                        {getPasswordChecks(newPassword).map((check) => (
                                            <p key={check.label} className={`text-xs flex items-center gap-1 ${check.met ? 'text-green-600' : 'text-red-500'}`}>
                                                <span>{check.met ? '✓' : '✗'}</span> {check.label}
                                            </p>
                                        ))}
                                    </div>
                                )}

                                <div>
                                    <Label htmlFor="confirmNewPassword" className="text-xs font-medium text-gray-600 uppercase block mb-1">
                                        Confirm New Password
                                    </Label>
                                    <Input
                                        id="confirmNewPassword"
                                        type="password"
                                        value={confirmNewPassword}
                                        onChange={(e) => setConfirmNewPassword(e.target.value)}
                                        required
                                        placeholder="Re-enter new password"
                                        className={`h-10 px-4 py-0 text-sm bg-gray-100 text-gray-800 rounded-lg ${
                                            confirmNewPassword && newPassword !== confirmNewPassword ? 'border-red-500' : 'border-gray-300'
                                        }`}
                                    />
                                    {confirmNewPassword && newPassword !== confirmNewPassword && (
                                        <p className="text-xs text-red-500 mt-1">Passwords do not match</p>
                                    )}
                                </div>

                                <Button type="submit" disabled={isLoading} className="w-full h-10 font-medium text-sm rounded-lg mt-4">
                                    {isLoading ? (
                                        <>
                                            <span className="mr-2 h-4 w-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                            Resetting...
                                        </>
                                    ) : 'CONFIRM & RESET'}
                                </Button>

                                <div className="flex justify-between text-xs">
                                    <Button
                                        type="button"
                                        variant="link"
                                        onClick={() => setStep(1)}
                                        className="text-primary p-0 h-auto"
                                    >
                                        Resend Code
                                    </Button>
                                    <Button
                                        type="button"
                                        variant="link"
                                        onClick={() => navigate('/login')}
                                        className="text-primary p-0 h-auto"
                                    >
                                        Back to Sign in
                                    </Button>
                                </div>
                            </form>
                        )}
                    </div>
                </div>
            </Card>
        </div>
    );
};

export default ForgotPassword;
